import{z as l,x as B,o as t,c,q as E,j as o,D as i,d as a,s as r,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"setuid 与粘滞位","description":"","frontmatter":{"title":"setuid 与粘滞位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/setuid-sticky.md","filePath":"cs/setuid-sticky.md","lastUpdated":1791063341000}'),u={name:"cs/setuid-sticky.md"};function p(A,e,m,h,D,C){const d=B("Mermaid");return t(),c("div",null,[e[2]||(e[2]=E('<h1 id="setuid-与粘滞位" tabindex="-1">setuid 与粘滞位 <a class="header-anchor" href="#setuid-与粘滞位" aria-label="Permalink to &quot;setuid 与粘滞位&quot;">​</a></h1><div class="epigraph"><p>setuid 可执行文件在 exec 后把有效用户换成文件属主；粘滞目录只允许用户删除自己的目录项。</p><footer>—— 据 Ritchie and Thompson 对 setuid 的原始设计；Bach；POSIX 整理</footer></div><p><a href="/cs/file-mode-bits">上一课</a>按有效身份检查 rwx。有些程序需要暂时以另一用户访问文件（口令改密），但不能把该用户的口令写进所有调用者。<a href="/cs/process-image">进程映像</a> 的 exec 会换映像。缺口是 <strong>setuid/setgid 与粘滞位</strong>：改有效身份，以及 <code>/tmp</code> 上的删除规则。本课讲机制，不讲如何利用错误配置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 passwd 必须以 root 写口令文件，又必须以普通用户调用，缺口是 exec 时把有效 uid 设为二进制文件的属主（通常 root），真实 uid 仍记录调用者。内核在打开文件时用有效 uid。粘滞位在目录上：即使目录可写，也不得删别人的文件名。setgid 对文件类似换有效 gid；对目录可表示「新建文件继承目录组」。</p><p>本课不把 Linux 文件能力（capabilities）的全部位图写完。</p><p><span class="marginnote">解释器脚本的 setuid 历史上不安全，许多系统忽略脚本上的 setuid。可执行映像才提升。本课不给绕过步骤。</span></p><p><span class="marginnote">直觉类比：setuid 像一张「进入这个房间后临时换成属主工牌」的门禁——只有运行 passwd 这个程序、且只在这扇门内生效；程序退出或换别的门，工牌收回，真实身份（真实 uid）从始至终没变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>chmod u+s</code>：mode 里 setuid 位置位。<code>execve</code> 通过 <a href="/cs/file-mode-bits">模式</a> 的 x 检查后，若 setuid 则 euid←属主。后续 <code>open</code> 用 euid。程序可 <code>seteuid</code> 在真实与有效之间收放（受规则限制）。粘滞目录：<code>unlink</code>/<code>rename</code> 额外检查调用者是否为目录项属主或有特权。VFS 在这些系统调用里执行检查，FS 只存那一位。</p><p><span class="marginnote">数字实例：权限位共 12 位，八进制写法里最高一位就是这三个特殊位——setuid = 4000、setgid = 2000、粘滞位 = 1000。所以 <code>chmod 4755 passwd</code> 开头的 4 就是 setuid：属主 rwx、组和其他人 r-x。见过 <code>/usr/bin/passwd</code> 的权限串 <code>rwsr-xr-x</code> 吗？那个 s 就占着属主 x 的位置。</span></p>',11)),(t(),o(n,null,{default:i(()=>[r(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXEC%5B%22exec%20%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%96%87%E4%BB%B6%22%5D%20--%3E%20SUID%7B%22setuid%3F%22%7D%0A%20%20SUID%20--%3E%7C%E6%98%AF%7C%20EUID%5B%22euid%20%3D%20%E6%96%87%E4%BB%B6%E5%B1%9E%E4%B8%BB%22%5D%0A%20%20STICK%5B%22%E7%B2%98%E6%BB%9E%E7%9B%AE%E5%BD%95%20unlink%22%5D%20--%3E%20OWN%5B%22%E9%A1%BB%E6%98%AF%E8%AF%A5%E9%A1%B9%E5%B1%9E%E4%B8%BB%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s("h2",{id:"机制",tabindex:"-1"},[a("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=s("p",null,[a("setuid 是受控的身份切换，把「需特权的操作」收进特定二进制，而不是给用户永久 root。粘滞位修复「目录可写则人人可删别人文件」。两者都是 mode 的额外位，不改页表。"),s("a",{href:"/cs/syscall-path"},"系统调用路径"),a(" 上检查发生在 VFS，与具体 ext4 日志无关。")],-1)),e[5]||(e[5]=s("p",null,"安全课会谈最小特权与审计；本课只把位接到 exec 与 unlink。",-1)),(t(),o(n,null,{default:i(()=>[r(d,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%20unlink%20%2Ftmp%2Fa%22%5D%20--%3E%20W%7B%22%E7%9B%AE%E5%BD%95%E5%AF%B9%E8%AF%A5%E7%94%A8%E6%88%B7%E5%8F%AF%E5%86%99%3F%22%7D%0A%20%20W%20--%3E%7C%E5%90%A6%7C%20DENY%5B%22%E6%8B%92%E7%BB%9D%20EPERM%22%5D%0A%20%20W%20--%3E%7C%E6%98%AF%7C%20S%7B%22%E7%9B%AE%E5%BD%95%E6%9C%89%E7%B2%98%E6%BB%9E%E4%BD%8D%3F%22%7D%0A%20%20S%20--%3E%7C%E5%90%A6%7C%20OK%5B%22%E7%9B%B4%E6%8E%A5%E5%88%A0%E9%99%A4%22%5D%0A%20%20S%20--%3E%7C%E6%98%AF%7C%20O%7B%22%E8%AF%A5%E9%A1%B9%E5%B1%9E%E4%B8%BB%20%3D%3D%20%E8%B0%83%E7%94%A8%E8%80%85%20euid%3F%22%7D%0A%20%20O%20--%3E%7C%E6%98%AF%7C%20OK2%5B%22%E5%88%A0%E9%99%A4%E6%88%90%E5%8A%9F%22%5D%0A%20%20O%20--%3E%7C%E5%90%A6%7C%20R%7B%22%E8%B0%83%E7%94%A8%E8%80%85%E6%98%AF%E7%9B%AE%E5%BD%95%E5%B1%9E%E4%B8%BB%E6%88%96%E6%9C%89%E7%89%B9%E6%9D%83%3F%22%7D%0A%20%20R%20--%3E%7C%E6%98%AF%7C%20OK3%5B%22%E5%88%A0%E9%99%A4%E6%88%90%E5%8A%9F%22%5D%0A%20%20R%20--%3E%7C%E5%90%A6%7C%20DENY2%5B%22%E6%8B%92%E7%BB%9D%E5%88%A0%E9%99%A4%22%5D%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<p><span class="marginnote">常见误区：初学者容易以为粘滞位限制了「写入」；它其实只管删除与改名——任何用户仍可以在 /tmp 里自由创建自己的文件，只是不能动别人的目录项。这也是为什么叫 sticky（粘住）：目录项被「粘」在属主手里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析具体漏洞，不讲提权步骤。nosuid 挂载可忽略 setuid，容器课会再提。下一课离开权限，进入块层：许多已经允许的读写，请求如何排序送向设备。</p><p>后课默认：身份与 <code>/tmp</code> 规则已定。块请求的电梯与多队列，下一课磁盘调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>setuid 在 exec 时改 euid；粘滞位限制可写目录上的删除。</li><li>检查在 VFS；本课不讲利用。</li><li>块层调度是下一课。</li><li>出处：Ritchie and Thompson；Bach, <em>UNIX</em>；POSIX。</li></ul>',6))])}const x=l(u,[["render",p]]);export{f as __pageData,x as default};
